namespace ghidra.feature.vt.gui.provider.markuptable;



using org.apache.commons.lang3;

using docking.widgets.table;
using ghidra.docking.settings;
using ghidra.feature.vt.api.stringable;
using ghidra.feature.vt.api.util;
using ghidra.util.exception;
using ghidra.util.table.column;

public class MarkupItemValueRenderer : AbstractGhidraColumnRenderer<Stringable> {

	/* @Override */
	public Component getTableCellRendererComponent(GTableCellRenderingData data) {

		base.getTableCellRendererComponent(data);

		object value = data.getValue();
		bool isSelected = data.isSelected();

		if (!(value is Stringable) && value != null) {
			throw new AssertException("Incorrect column value for the markup item value column: " +
				value.GetType().getSimpleName());
		}

		string text = asString((Stringable) value);
		configureRendererForStringable((Stringable) value, text, isSelected);

		return this;
	}

	private string asString(Stringable stringable) {

		if (stringable == null) {
			return "";
		}

		string text = stringable.getDisplayString();
		if (StringUtils.isBlank(text)) {
			return ""; // don't add any special decoration
		}

		return text;
	}

	private void configureRendererForStringable(Stringable stringable, string text,
			bool isSelected) {

		if (stringable == null) {
			setText(text);
			return;
		}

		if (StringUtils.isBlank(text)) {
			setText(text);
			return; // don't add any special decoration
		}

		setText(text);

		bool isSymbol = false;
		if (stringable is SymbolStringable) {
			isSymbol = true;
		}
		else if (stringable is FunctionNameStringable) {
			isSymbol = true;
		}
		else if (stringable is MultipleSymbolStringable) {
			isSymbol = true;
		}

		if (!isSymbol) {
			return;
		}

		setBold();

//		This should not be needed
//		if (!isSelected) {
//			setForeground(Colors.FOREGROUND);
//		}

		return;
	}

	/* @Override */
	public string getFilterString(Stringable t, Settings settings) {
		return asString(t);
	}
}
